        spotify: '<svg viewBox="0 0 24 24"><path d="M12 2C6.477 2 2 6.477 2 12s4.477 10 10 10 10-4.477 10-10S17.523 2 12 2zm4.586 14.424c-.18.295-.563.387-.857.207-2.35-1.434-5.308-1.758-8.793-.963-.335.077-.67-.133-.746-.469-.077-.334.132-.67.467-.745 3.808-.87 7.076-.51 9.721 1.113.295.18.388.563.208.857zm1.225-2.723c-.226.367-.706.482-1.072.257-2.687-1.652-6.785-2.131-9.965-1.166-.413.127-.849-.107-.976-.52-.127-.414.107-.849.52-.976 3.632-1.102 8.147-.568 11.236 1.332.366.226.481.707.257 1.073zm.105-2.835C14.692 8.95 8.085 8.731 4.24 9.898c-.495.15-1.02-.13-1.17-.624-.15-.494.13-1.018.625-1.169 4.415-1.34 11.688-1.088 15.688 1.285.445.264.59.838.326 1.283-.264.444-.838.59-1.283.326z"/></svg>',
        generic: '<svg fill="none" height="14" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="14"><circle cx="12" cy="12" r="10"/><line x1="2" x2="22" y1="12" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>'
      };

      for (var i = 0; i < links.length; i++) {
        var a = links[i];
        if (a.querySelector('svg')) continue;

        var href = (a.getAttribute('href') || '').toLowerCase();
        var text = (a.textContent || '').toLowerCase().trim();
        var iconHtml = icons.generic;

        if (href.indexOf('facebook.com') > -1 || text.indexOf('face') > -1) {
          iconHtml = icons.facebook;
          a.classList.add('social-fb');
        } else if (href.indexOf('instagram.com') > -1 || text.indexOf('insta') > -1) {
          iconHtml = icons.instagram;
          a.classList.add('social-ig');
        } else if (href.indexOf('wa.me') > -1 || href.indexOf('whatsapp.com') > -1 || text.indexOf('what') > -1) {
          iconHtml = icons.whatsapp;
          a.classList.add('social-wa');
        } else if (href.indexOf('youtube.com') > -1 || href.indexOf('youtu.be') > -1 || text.indexOf('you') > -1) {
          iconHtml = icons.youtube;
          a.classList.add('social-yt');
        } else if (href.indexOf('twitter.com') > -1 || href.indexOf('x.com') > -1 || text.indexOf('twit') > -1 || text === 'x') {
          iconHtml = icons.twitter;
          a.classList.add('social-x');
        } else if (href.indexOf('tiktok.com') > -1 || text.indexOf('tik') > -1) {
          iconHtml = icons.tiktok;
          a.classList.add('social-tk');
        } else if (href.indexOf('t.me') > -1 || href.indexOf('telegram') > -1 || text.indexOf('tele') > -1) {
          iconHtml = icons.telegram;
          a.classList.add('social-tg');
        } else if (href.indexOf('spotify.com') > -1 || text.indexOf('spot') > -1) {
          iconHtml = icons.spotify;
          a.classList.add('social-sp');
        }

        a.insertAdjacentHTML('afterbegin', iconHtml);
      }
    }
    enhanceSocialIcons();

    // REPRODUCTOR: REPRODUCIR / DETENER TRANSMISIÓN
    function toggleLiveRadio() {
      var audio = document.getElementById('liveRadioStream');
      if (!audio) return;
      setupRadioAudioListeners();

      var cfg = getRadioSettings();

      if (!isLivePlaying) {
        var freshUrl = prepareStreamUrl(cfg.streamUrl);
        audio.src = freshUrl;
        audio.load();

        audio.play().then(function() {
          isLivePlaying = true;
          updatePlayerUI(true, false);
          if (cfg.metadata && cfg.metadata.enabled) {
            fetchLiveMetadata();
            if (!metadataPollTimer) metadataPollTimer = setInterval(fetchLiveMetadata, 15000);
          }
        }).catch(function(err) {
          isLivePlaying = false;
          updatePlayerUI(false, true);
          console.warn('Error al iniciar stream o señal apagada:', err);
        });
      } else {
        // DETENER (STOP REAL): Cortar conexión y vaciar buffer
        audio.pause();
        audio.removeAttribute('src');
        audio.load();
        isLivePlaying = false;
        updatePlayerUI(false, false);
        if (metadataPollTimer) {
          clearInterval(metadataPollTimer);
          metadataPollTimer = null;
        }
      }
    }

    // CONTROL DE VOLUMEN
    function changeRadioVolume(vol) {
      var audio = document.getElementById('liveRadioStream');
      if (audio) {
        audio.volume = parseFloat(vol);
      }
    }

    // COMPARTIR EN FACEBOOK (VENTANA EMERGENTE)
    function shareOnFacebook(e, url) {
      if (e) e.preventDefault();
      var shareUrl = url || ('https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(window.location.href));
      var width = 620;
      var height = 450;
      var left = (window.innerWidth / 2) - (width / 2);
      var top = (window.innerHeight / 2) - (height / 2);
      window.open(shareUrl, 'fbShareWindow', 'toolbar=no, location=no, directories=no, status=no, menubar=no, scrollbars=no, resizable=no, copyhistory=no, width=' + width + ', height=' + height + ', top=' + top + ', left=' + left);
    }

    function sharePostToFacebook(btn) {
      var postUrl = btn.getAttribute('data-url') || window.location.href;
      var shareUrl = 'https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(postUrl);
      shareOnFacebook(null, shareUrl);
    }

    // COPIAR ENLACE AL PORTAPAPELES
    function copyPostLink(btn) {
      var postUrl = btn.getAttribute('data-url') || window.location.href;
      if (navigator.clipboard) {
        navigator.clipboard.writeText(postUrl).then(function() {
          showToastNotification('¡Enlace copiado al portapapeles!');
        }).catch(function() {
          fallbackCopyText(postUrl);
        });
      } else {
        fallbackCopyText(postUrl);
      }
    }

    function fallbackCopyText(text) {
      var tempInput = document.createElement('input');
      tempInput.value = text;
      document.body.appendChild(tempInput);
      tempInput.select();
      document.execCommand('copy');
      document.body.removeChild(tempInput);
      showToastNotification('¡Enlace copiado al portapapeles!');
    }

    function showToastNotification(msg) {
      var toast = document.getElementById('toastCopyNotification');
      if (toast) {
        toast.textContent = msg;
        toast.classList.add('show');
        setTimeout(function() {
          toast.classList.remove('show');
        }, 2800);
      }
    }

    // NORMALIZAR Y DETECTAR ENLACES INTERNOS DEL BLOG (EVITA PROBLEMAS HTTP/HTTPS Y DOMINIOS BLOGSPOT CCTLD)
    function toCleanInternalUrl(rawUrl) {
      if (!rawUrl) return null;
      try {
        var parsed = new URL(rawUrl, window.location.href);

        // Comprobar dominio y variantes ccTLD de Blogger (.blogspot.com vs .blogspot.pe, etc.)
        var currentHost = window.location.hostname.toLowerCase();
        var linkHost = parsed.hostname.toLowerCase();

        var isSameHost = (linkHost === currentHost);
        var isBlogspotSister = false;
        if (currentHost.indexOf('.blogspot.') > -1 && linkHost.indexOf('.blogspot.') > -1) {
          var currentSub = currentHost.split('.blogspot.')[0];
          var linkSub = linkHost.split('.blogspot.')[0];
          if (currentSub === linkSub) {
            isBlogspotSister = true;
          }
        }

        if (isSameHost || isBlogspotSister) {
          // Forzar protocolo actual y dominio actual para evitar Mixed Content y CORS
          return window.location.origin + parsed.pathname + parsed.search;
        }
      } catch (e) {
        return null;
      }
      return null;
    }

    // SINCRONIZAR VISUALMENTE LA PESTAÑA ACTIVA TRAS NAVEGACIÓN
    function syncActiveTabs(targetUrl) {
      try {
        var parsedTarget = new URL(targetUrl || window.location.href, window.location.origin);
        var targetPath = parsedTarget.pathname.replace(/\/+$/, '') || '/';
        var tabs = document.querySelectorAll('.content-tabs-list .tab-item');
        if (!tabs.length) return;

        var foundActive = false;
        for (var i = 0; i < tabs.length; i++) {
          var a = tabs[i].querySelector('a');
          tabs[i].classList.remove('active');
          var dot = a ? a.querySelector('.tab-active-dot') : null;
          if (dot) dot.remove();

          if (a) {
            var aParsed = new URL(a.href, window.location.origin);
            var aPath = aParsed.pathname.replace(/\/+$/, '') || '/';
            if (aPath === targetPath) {
              tabs[i].classList.add('active');
              var newDot = document.createElement('span');
              newDot.className = 'tab-active-dot';
              a.insertBefore(newDot, a.firstChild);
              foundActive = true;
            }
          }
        }

        // Si estamos en la página principal ('/') y ninguna pestaña coincidió exactamente, activar la primera (Blog / Inicio)
        if (!foundActive && targetPath === '/') {
          if (tabs[0]) {
            tabs[0].classList.add('active');
            var firstA = tabs[0].querySelector('a');
            if (firstA && !firstA.querySelector('.tab-active-dot')) {
              var dotFirst = document.createElement('span');
              dotFirst.className = 'tab-active-dot';
              firstA.insertBefore(dotFirst, firstA.firstChild);
            }
          }
        }
      } catch (err) {
        console.warn('Aviso en sincronización de pestañas:', err);
      }
    }

    // NAVEGACIÓN AJAX FLUIDA (PARA NO CORTAR LA RADIO AL NAVEGAR ENTRE PÁGINAS Y NOTICIAS)
    document.addEventListener('click', function(e) {
      var link = e.target.closest('a');
      if (!link) return;

      // No interceptar si tiene target="_blank" o descarga
      if (link.getAttribute('target') && link.getAttribute('target') !== '_self') return;
      if (link.hasAttribute('download')) return;

      var rawHref = link.getAttribute('href') || link.href;
      if (!rawHref || rawHref.indexOf('#') === 0 || rawHref.indexOf('javascript:') === 0) return;

      // Verificar si es pestaña de páginas o enlace interno
      var tabItem = link.closest('.tab-item');
      var internalUrl = toCleanInternalUrl(rawHref);

      if (tabItem || internalUrl) {
        var targetUrl = internalUrl;
        if (!targetUrl && tabItem) {
          try {
            var pUrl = new URL(rawHref, window.location.href);
            targetUrl = window.location.origin + pUrl.pathname + pUrl.search;
          } catch (err) {
            targetUrl = window.location.origin + '/';
          }
        }

        if (!targetUrl) return;

        // Si ya estamos exactamente en esa misma URL, solo subir suavemente
        var currentClean = window.location.origin + window.location.pathname + window.location.search;
        if (targetUrl === currentClean || (targetUrl === window.location.origin + '/' && (window.location.pathname === '/' || window.location.pathname === ''))) {
          e.preventDefault();
          window.scrollTo({ top: 0, behavior: 'smooth' });
          return;
        }

        e.preventDefault();

        // Respuesta visual instantánea en las pestañas
        if (tabItem) {
          var allTabs = document.querySelectorAll('.content-tabs-list .tab-item');
          for (var i = 0; i < allTabs.length; i++) {
            allTabs[i].classList.remove('active');
            var oldDot = allTabs[i].querySelector('.tab-active-dot');
            if (oldDot) oldDot.remove();
          }
          tabItem.classList.add('active');
          var activeA = tabItem.querySelector('a');
          if (activeA && !activeA.querySelector('.tab-active-dot')) {
            var dotElem = document.createElement('span');
            dotElem.className = 'tab-active-dot';
            activeA.insertBefore(dotElem, activeA.firstChild);
          }
        }

        loadPageDynamic(targetUrl, true);
      }
    });

    // CAPTURAR ENVÍO DEL BUSCADOR (PARA NO CORTAR LA RADIO EN VIVO)
    document.addEventListener('submit', function(e) {
      var form = e.target.closest('.news-search-form');
      if (!form) return;

      e.preventDefault();
      var input = form.querySelector('input[name="q"]');
      var query = input ? input.value.trim() : '';
      if (!query) return;

      var action = form.getAttribute('action') || (window.location.origin + '/search');
      var cleanAction = toCleanInternalUrl(action) || (window.location.origin + '/search');
      var separator = cleanAction.indexOf('?') !== -1 ? '&' : '?';
      var targetUrl = cleanAction + separator + 'q=' + encodeURIComponent(query);
      loadPageDynamic(targetUrl, true);
    });

    function loadPageDynamic(url, pushHistory) {
      var container = document.getElementById('ajax-main-container');
      if (!container) {
        window.location.href = url;
        return;
      }
      container.classList.add('loading');

      fetch(url)
        .then(function(res) {
          if (!res.ok) throw new Error('HTTP ' + res.status);
          return res.text();
        })
        .then(function(html) {
          var parser = new DOMParser();
          var doc = parser.parseFromString(html, 'text/html');
          var newContent = doc.getElementById('ajax-main-container');

          if (newContent) {
            container.innerHTML = newContent.innerHTML;
            document.title = doc.title;
            if (pushHistory) {
              window.history.pushState({ path: url }, doc.title, url);
            }
            window.scrollTo({ top: 0, behavior: 'smooth' });

            // Sincronizar estado activo de las pestañas
            syncActiveTabs(url);
          } else {
            window.location.href = url;
          }
          container.classList.remove('loading');
        })
        .catch(function(err) {
          console.warn('Aviso en carga dinámica, recargando página normalmente:', err);
          window.location.href = url;
        });
    }

    window.addEventListener('popstate', function() {
      loadPageDynamic(window.location.href, false);
    });
  //
